-- GENERATED by `wfj generate` from data/gossip/gossip-5d.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5d134bf1b1e4c583"] = { "Tempesta di sabbia in arrivo da sud, mettetevi al ripa... Quella non è una tempesta di sabbia! ARRIVA L'ESERCITO QIRAJI!", "." },
  ["5d148aaa216104cd"] = { "Gloria a {name}, <sterminatore/sterminatrice> di Hakkar ed <eroe/eroina> di Azeroth!", "." },
  ["5d265b2ac02e837b"] = { "Niente batte il suono di un motore a vapore a doppio carburatore e anello a forcella che brucia pietra di fuoco pura!", "." },
  ["5d2a5ddda00cfbc8"] = { "Cosa sono queste Tonk Control Console?", "." },
  ["5d2f7d9299dd422b"] = { "Lanciami!", "." },
  ["5d2fc7cb53c115c5"] = { "Lui sta in anello interno del ⟦Rogues' Quarter=Quartiere dei Ladri⟧.", "." },
  ["5d3427f3f907b2ad"] = { "Controlla quella cella, {name}. Se c'è qualcuno vivo là dentro, dobbiamo tirarlo fuori.", "." },
  ["5d3bbd817ccdbb54"] = { "Faresti meglio a darmi man forte stavolta!", "." },
  ["5d3c66495e000d78"] = { "%s cammina avanti e indietro in attesa della battaglia.", "." },
  ["5d44fada69a5a13a"] = { "«Un'abilità per chi desidera superare gli ostacoli.» Credo sia così che Faelyssa descrive le sue competenze.\n\nSe la pensi come lei, raggiungi l'⟦Cenarion Enclave=Enclave Cenariana⟧ nella parte settentrionale di Darnassus, dove tiene le sue lezioni.", "." },
  ["5d49e37eb03c2114"] = { "Gloom'rel, svelami i tuoi segreti!", "." },
  ["5d4c2d887ac1692e"] = { "Salute, <ragazzo/ragazza>! Se cerchi i migliori affari che troverai fuori da ⟦Ironforge=Forgiardente⟧, sei nel posto giusto.", "." },
  ["5d4ed0b350341580"] = { "Chiudi gli occhi. Dormi.", "." },
  ["5d50a6cde272423c"] = { "Ora cerchiamo un'Arpia ignara!", "." },
  ["5d510e641e306007"] = { "Abbiamo cominciato a ritorcere la peste del Flagello contro di loro, ma la nostra presa è a dir poco precaria! Aiuta la causa sabotando i loro calderoni!", "." },
  ["5d5f09a1c43c3dc1"] = { "Gli ogre Gordunni invadono le nostre terre. Mandiamo tutti quelli disposti ad affrontarli tra le rovine profanate di Feralas.", "." },
  ["5d6abc2613f9bcd3"] = { "L'infernale è uno dei demoni più potenti che uno stregone possa sperare di avere al proprio fianco in battaglia. La creatura è forte, ben corazzata e infligge colpi devastanti a qualsiasi nemico. Se scegliessi di infondere lo spirito di un infernale nella tua arma, otterresti alcuni di questi vantaggi: più Salute, rigenerazione e simili.\n\nSe vuoi saperne di più sui vilsegugi, dovresti parlare con Wytula, di fronte a me.", "." },
  ["5d6ce7dbd984cd40"] = { "{class}, ti prego, ascolta ciò che ho da dire. L'⟦Alliance=Alleanza⟧ e l'⟦Horde=Orda⟧ si preparano a una guerra contro i silitidi e i loro padroni di ⟦Ahn'Qiraj=Ahn'qiraj⟧. Qualsiasi aiuto tu possa dare sarà molto apprezzato. Come vedi, qui raccolgo lingotti di torio per lo sforzo bellico. Dobbiamo raccoglierne $2012w in tutto, e al momento ne abbiamo $2011w.", "." },
  ["5d774c2182a28c39"] = { "Non profanare queste rovine, mortale. <Un lampo di luce accecante ti avvolge. Una creatura fatta interamente di fiamme è l'unica cosa che ricordi di aver visto.>", "." },
  ["5d796deef2659412"] = { "%s sbuffa profondamente mentre si ferma.", "." },
  ["5d7df209f61631ff"] = { "Questo posto... è maledetto.\n\nCe l'ho fatta a malapena a fuggire, e non sopporto l'idea di scendere di nuovo nei tunnel.\n\nMio fratello e le mie sorelle, però... non hanno avuto la stessa fortuna. Intrappolati là dentro, sono in preda alla febbre per la nebbia corrotta che emana dal giardino maligno che cresce laggiù.\n\nTi prego, devi aiutarli.", "." },
  ["5d83dd8cd9da89e8"] = { "È... la... fine.", "." },
  ["5d8443caa5fe8971"] = { "L'⟦Alliance=Alleanza⟧ vince!", "." },
  ["5d84640c0053c225"] = { "La mia risposta è Ner'zhul.", "." },
  ["5d8701526dd76bd7"] = { "%s comincia a riprendere le forze!", "." },
  ["5d8e3a0f6101abaa"] = { "{name}, la traduzione è finita!", "." },
  ["5d8e4d059e52c1cf"] = { "Prego per queste cose.", "." },
  ["5d9683749400cd3f"] = { "La fenditura si chiuse e Krixix sparì! Inghiottito per intero!\n\nFai attenzione, {race}: ciò che desideri potrebbe benissimo diventare ciò che non vuoi. Stai giocando con esseri e arcani più antichi del tempo stesso!\n\nSe Krixix è vivo e ha le informazioni che cerchi, una cosa è certa: non le cederà. Ha affrontato terrori di gran lunga peggiori di quelli che potresti mai sognare di infliggere.", "." },
  ["5d9c583d7207144d"] = { "Staghelm e i suoi eserciti furono chiaramente sopraffatti dal flusso inarrestabile delle truppe di Rajaxx che si riversavano su ⟦Silithus=Silitus⟧. Sembrerebbe, però, che Staghelm fosse più di un semplice fastidio per i Qiraji. Sotto Staghelm, tutti gli eserciti degli elfi della notte si erano uniti per difendere Kalimdor, rallentando di molto le forze qiraji.", "." },
  ["5d9db59af06782b7"] = { "Oh, che orrore! Che tragedia! Siamo sul punto di una svolta, eppure tutto potrebbe andare perduto.", "." },
  ["5da144c947260b5d"] = { "Il ⟦Iceblood Graveyard=Cimitero di Brinarossa⟧ è sotto attacco! Se nessuno interviene, l'⟦Alliance=Alleanza⟧ lo conquisterà!", "." },
  ["5da2aaa56115ec93"] = { "Santo Krakle! La temperatura è di 428.000 gradi Kraklenheit!", "." },
  ["5da3f6dfacfae3b3"] = { "Ehi, <amico/signora>, pensi di potermi dare una mano con una cosa? Sono proprio nei guai...", "." },
  ["5db3c29caee68f71"] = { "Beh... mi secca ammetterlo, ma se vuoi continuare l'addestramento devi parlare con mia sorella. Non ne so quanto lei... per ora! È là, vicino all'auto a razzo.", "." },
  ["5db6fa7a1fdb52c4"] = { "Andò perduto quando cadde la Violet Citadel... ridotto in quarantadue pezzi.", "." },
  ["5db893654519e2e9"] = { "Ben <trovato/trovata>, <amico/amica>. Sono l'ufficiale Garush, e faccio parte con orgoglio di un'organizzazione presente in tutto il mondo, nota come ⟦Argent Dawn=Alba d'Argento⟧. La nostra causa è combattere con rapidità e senza pietà ogni elemento del male che emerga ad Azeroth. Non siamo un organismo politico, né desideriamo mai diventarlo. La nostra causa è una sola, e per questo chiamiamo amici sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧: amici nella causa di estirpare il male!\n\nPer l'Alba, <fratello/sorella> <mio/mia>!", "." },
  ["5dc07cd0cbc381f6"] = { "Le Plates of Uldum sono dischi sintetizzati dai Creatori che permettono di accedere al complesso di Uldum. Questi dischi custodiscono e conservano dati specifici sulle attività dei Creatori in quel luogo.\n\nFisicamente hanno quasi la stessa circonferenza della serie di dischi che possiedi già. I loro segni, però, si riferiscono direttamente a informazioni su Uldum, anziché sul complesso di Uldaman.", "." },
  ["5dd16595997a5004"] = { "Che c'è adesso, {class}? Non ho tutto il giorno. L'⟦Horde=Orda⟧ ha completato le sue raccolte e ora aspetta solo che l'⟦Alliance=Alleanza⟧ si organizzi e faccia lo stesso. Forse dovresti essere là fuori a cercare i pezzi dello Scettro delle Sabbie Mutevoli, così da suonare il gong sull'Altare dello Scarabeo, aprire i cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧ e dare così inizio alla guerra?", "." },
  ["5dd674e97915fd6b"] = { "La prima uccisione è mia! Qualcuno vuole scommettere?", "." },
  ["5dd9401edb5c6712"] = { "No, non un altro! Avrò le vostre teste per questa atrocità!", "." },
  ["5dda5d1cddca5794"] = { "Ehi, tu! Fai attenzione! I tuoi sacri doni shen'dorei non vanno usati per divertimento!", "." },
  ["5de01066ad6d3e52"] = { "Ehi! Grazie per avermi salvato la pelle! Credo che starò un po' a terra finché non avrò recuperato le forze.", "." },
  ["5de5171e0f2ac009"] = { "Ci sono basi che vanno apprese. Trianna è qui vicino: parla con lei e torna da me più tardi.", "." },
  ["5de83dc8d2701990"] = { "Ok, basta! Mi arrendo!", "." },
  ["5df0430d2f77ad81"] = { "Oh, ho di nuovo vagato chissà dove. Scusami.", "." },
  ["5df4d02dad5f856b"] = { "Mi serve un ⟦Scrying Scope=Mirino della Chiaroveggenza⟧ per osservare il Globe of Scrying, Ryson.", "." },
  ["5dfdf61c682ccd77"] = { "Circola, <zoticone/zoticona>.", "." },
})
